1	// Manifest-based routing (shared surface). A feature is a NEW file at features/<name>/feature.tsx
2	// that exports a `feature: Feature`; it is discovered here via import.meta.glob, so adding a page is
3	// a new file — never an edit to this router (DESIGN.md §8).
4	import type { ComponentType } from 'react';
5	
6	export type Feature = {
7	  id: string; // section id -> nav-<id> data-testid
8	  label: string; // nav link text
9	  Page: ComponentType;
10	};
11	
12	const modules = import.meta.glob<{ feature: Feature }>('../features/*/feature.tsx', { eager: true });
13	
14	export const features: Feature[] = Object.values(modules)
